#!/usr/bin/env python3
# slot. superchis: extract the M1 subset of slot. advance's built-in art (task 4.1/4.2).
#
# Reads the pinned, read-only vendor/slot-advance/common/slot_assets.h (a2a2fe9, v1.2.4,
# GPL-3.0-or-later, artwork by Markus) and writes a C file with just the arrays the M1 carousel
# draws: wood background, dark skeuomorphic front/back bands, the three plain cartridge
# silhouettes, the 6x12 font, and the boot splash (RLE-packed: it is mostly black).
# Nothing is copied into the repo; the generated file (src/slot/slot_art_gen.c) is a build output.
# The full pack mechanism (all themes, compression, sounds) is task 6.1.
#
# usage: slot_assets_gen.py <vendor slot_assets.h> <out.c>
import re, sys

src = open(sys.argv[1]).read()
arrays = {}
for m in re.finditer(r'static const unsigned (short|char) (\w+)\[[^\]]+\](?:\[\d+\])? = \{(.*?)\};', src, re.S):
    arrays[m.group(2)] = [int(x, 0) for x in re.findall(r'0x[0-9a-fA-F]+|\d+', m.group(3))]

def emit(f, ctype, name, size, vals, per=16):
    assert len(vals) == size, (name, len(vals), size)
    f.write('const %s %s[%d] = {\n' % (ctype, name, size))
    for i in range(0, size, per):
        f.write('  ' + ','.join(str(v) for v in vals[i:i + per]) + ',\n')
    f.write('};\n\n')

with open(sys.argv[2], 'w') as f:
    f.write('/*\n'
            ' * GENERATED by tools/slot_assets_gen.py from vendor/slot-advance/common/slot_assets.h\n'
            ' * (slot. advance v1.2.4, commit a2a2fe9). Do not edit; not committed.\n'
            ' * Artwork by Markus (MarkusMaribu) for slot.; font and bands from slot. advance.\n'
            ' * Licence: GPL-3.0-or-later (see NOTICE.md).\n'
            ' */\n#include <stdint.h>\n#include "slot/slot_art.h"\n\n')
    emit(f, 'uint16_t', 'slot_background', 38400, arrays['slot_background'])
    emit(f, 'uint16_t', 'slot_back_dark', 4560, arrays['slot_back_dark'])
    emit(f, 'uint16_t', 'slot_front_dark', 4560, arrays['slot_front_dark'])
    emit(f, 'uint16_t', 'slot_fallback_gba', 8520, arrays['slot_fallback_gba'])
    emit(f, 'uint16_t', 'slot_fallback_gb', 11648, arrays['slot_fallback_gb'])
    emit(f, 'uint16_t', 'slot_fallback_gbc', 11648, arrays['slot_fallback_gbc'])
    # font: [128][12] bytes
    font = arrays['slot_font']
    f.write('const unsigned char slot_font[128][12] = {\n')
    for c in range(128):
        f.write('  {' + ','.join(str(v) for v in font[c * 12:(c + 1) * 12]) + '},\n')
    f.write('};\n\n')
    # splash: (count, pixel) u16 pairs
    sp = arrays['slot_splash']
    assert len(sp) == 38400
    pairs, i = [], 0
    while i < len(sp):
        j = i
        while j < len(sp) and sp[j] == sp[i] and j - i < 65535:
            j += 1
        pairs += [j - i, sp[i]]
        i = j
    f.write('const uint16_t slot_splash_rle[%d] = {\n' % len(pairs))
    for i in range(0, len(pairs), 16):
        f.write('  ' + ','.join(str(v) for v in pairs[i:i + 16]) + ',\n')
    f.write('};\nconst unsigned slot_splash_rle_len = %d;\n' % len(pairs))
